6. 인간 찾기 (관찰)
- 바울이 변론하는 것을 허락하는 아그립바
- 변론을 통해 복음을 전하는 바울 

7. 하나님 찾기 (해석) 
- 바울을 통해 복음이 확장되게 하시는 하나님

8. 인간(해석):
- 바울은 아그립바 앞에서 자신을 변론함과 동시에 복음을 담대히 전했다.
- 아그립바 왕은 성전 관리권과 대제사장 임명권을 가질 정도로 종교적으로 영향력이 컸다. 그런 자가 하나님을 믿을 수 있었다면 참 좋았겠단 생각이 든다.
- 바울은 어디서든 누구에게든 복음 전했다. 신분의 높고 낮음이 중요하지 않았다.
- 나는 과연 나에게 영향력을 미칠 수 있는 사람에게 복음을 전할 수 있는지 되묻는다.
- 나는 아직 멀었다. 

9. 적용(나): 
- 토요일 행사에 제자들을 초청했다. 고심했지만 초청하길 잘한 것 같다. 직장 상사, 동료들에게도 복음을 전할 수 있는 사람이 되고 싶다.

