11. 또 모든 회당에서 여러 번 형벌하여 강제로 모독하는 말을 하게 하고 그들에 대하여 심히 격분하여 외국 성에까지 가서 박해하였고
12. 그 일로 대제사장들의 권한과 위임을 받고 다메섹으로 갔나이다
13. 왕이여 정오가 되어 길에서 보니 하늘로부터 해보다 더 밝은 빛이 나와 내 동행들을 둘러 비추는지라
