16. 일어나 너의 발로 서라 내가 네게 나타난 것은 곧 네가 나를 본 일과 장차 내가 네게 나타날 일에 너로 종과 증인을 삼으려 함이니
17. 이스라엘과 이방인들에게서 내가 너를 구원하여 그들에게 보내어
