19. 아그립바 왕이여 그러므로 하늘에서 보이신 것을 내가 거스르지 아니하고
20. 먼저 다메섹과 예루살렘에 있는 사람과 유대 온 땅과 이방인에게까지 회개하고 하나님께로 돌아와서 회개에 합당한 일을 하라 전하므로

