8. 인간(해석):
- 바울의 간증을 들어서일까?! 백부장 율리오는 바울을 친절히 대했다.
- 죄인의 신분이지만 많은 사람들은 바울이 죄 없음을 알았던 것 같다.
- 바울은 사람들의 이러한 행동 덕분에 소망을 품을 수 있지 않았을까?
- 남북청년연합 선교회도 소망을 품게 된다. 
- 지난주에 진행한 시사회에 개인적인 친분으로 왔지만 시사회를 통해 은혜를 받았다고 고백하는 지인이 많았다. 

- 우리의 사역은 외롭지 않다. 
- 바울이 탔던 배가 간신히 니도 맞은 편에 이르른 것 같이 
- 우리도 여기까지 오기 쉽지 않았다. 그러나 얼마나 감사한 일인가? 
- 더욱 하나님을 의지할 수 있게 되었고, 우리에게 주어진 비전을 확신하며 나아갈 수 있게 되었다.
- 앞으로의 사역도 간신히 나아가겠지만 분명한 것은 하나님께서 우리를 보호하신다는 것이다.
- 하나님만 의지하며 나아가는 남청연을 소망해본다.

9. 적용(나): 
- 바울의 여정처럼 우리의 여정도 쉽지 않겠지만 하나님의 은혜로 우리에게 주어진 소명을 잘 완수하길 기도한다.

