5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 선원들이 몰래 빠져나가려는 것을 보고 군인들에게 알리는 바울
- 바울의 말을 듣고 거룻줄을 끊어 버리는 군인들
- 사람들에게 먹을 것을 먹으라고 권하고 하나님께 기도하는 바울
- 열나흘 동안이나 주리고 있다가 바울의 말을 듣고 용기를 내어 먹을 것을 먹는 사람들
- 항만이 눈에 보이자 그 항만에 배를 댈 수 있는지 의논하는 사람들
- 배를 대려고 시도하다가 모래톱에 뱃머리가 박히고 배의 뒷부분은 파도에 부딪쳐 깨져감
- 죄수들이 도망갈까 염려되어 죽이려는 군인들
- 바울을 구하고자 배에서 탈출하여 육지로 가라고 명령하는 백부장

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 바울이 선원들이 빠져나가려는 것을 보고 군인들에게 우리가 살기 위해서 저들을 막아야 한다고 말함
- 주님께서 살려 주시겠다 말씀하셨으나, 자신이 할 일을 최선을 다해서 해내는 바울
- 열나흘을 주린 상태에서 폭풍과 싸우며 버텼으니 심히 피곤하여 잠들 수도 있는 상황에서 바울을 자지 않고 오히려 선원들을 주시하고 있었다.
- 하나님께서 바울에게 지치지 않는 정신력과 체력도 허락하셨을까?

- 군인들이 거룻줄을 끊었고 거룻배는 바다에 휩쓸려 멀리 떠내려 갔을 것이다.
- 위험에서 자신들만 거룻배를 타고 살고자 했던 선원들의 마음은 어땠을까?
- 선원들의 모습을 보고 분노가 치밀었을만도 한데, 바울과 군인들은 선원들을 벌하지 않았고, 결론적으로 276명은 모두 함께 구조되었다.

- 배에 탄 사람들을 구하기 위해 주린 배를 채울 것을 권하는 바울
- 위급한 상황에서 냉정함을 유지하며 모두 살기 위해서는 어떻게 해야 하는가 생각하고 모두를 지휘하는 바울

- 군인들은 배가 부서지자 죄수들을 죽이려 했으나, 바울을 살리고자 사람들에게 육지로 가라고 명하는 백부장
- 항해 전에도 바울을 신뢰했던 백부장은
- 폭풍을 속에서 하나님께 기도하고 침착한 가운데 사람들을 격려하고 지휘하는 바울을 보며 깊은 감명을 받았을 것이다. 

9.적용(나) 
- 육체적으로 극심한 피로를 느낄 때, 잘 버티다가도 어느 시점에서는 갑자기 정신적 피로를 느끼며 잠을 자곤 했다.
- 내가 폭풍과 싸우며 14일을 주렸다면 바울처럼 선원을 발견하고 사람들을 격려하고 지휘할 수 있었을까?
- 내 힘과 능력으로는 불가능하다.
- 아마 바울 또한 불가능했을 것이다. 모든 것은 하나님이 하시는 것이다.
- 하나님은 정말 놀라우신 분이다. 하나님을 의지하며 나아갈 뿐이다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-12-04', '사도행전', '28장 1~10절', '특별한 보호를 받는 바울', '[행28:1-10]
1 우리가 구조된 후에 안즉 그 섬은 멜리데라 하더라
2 비가 오고 날이 차매 원주민들이 우리에게 특별한 동정을 하여 불을 피워 우리를 다 영접하더라
3 바울이 나무 한 묶음을 거두어 불에 넣으니 뜨거움으로 말미암아 독사가 나와 그 손을 물고 있는지라
4 원주민들이 이 짐승이 그 손에 매달려 있음을 보고 서로 말하되 진실로 이 사람은 살인한 자로다 바다에서는 구조를 받았으나 공의가 그를 살지 못하게 함이로다 하더니
5 바울이 그 짐승을 불에 떨어 버리매 조금도 상함이 없더라
6 그들은 그가 붓든지 혹은 갑자기 쓰러져 죽을 줄로 기다렸다가 오래 기다려도 그에게 아무 이상이 없음을 보고 돌이켜 생각하여 말하되 그를 신이라 하더라
7 이 섬에서 가장 높은 사람 보블리오라 하는 이가 그 근처에 토지가 있는지라 그가 우리를 영접하여 사흘이나 친절히 머물게 하더니
8 보블리오의 부친이 열병과 이질에 걸려 누워 있거늘 바울이 들어가서 기도하고 그에게 안수하여 낫게 하매
9 이러므로 섬 가운데 다른 병든 사람들이 와서 고침을 받고
10 후한 예로 우리를 대접하고 떠날 때에 우리 쓸 것을 배에 실었더라

