3. 반복단어 찾기(형광펜 추천)
- 바울(3,5.8절)
- 원주민(2,4절)
- 섬(1,7,9절)
- 보블리오(7,8절)

4. 주제만들기: 특별한 보호를 받는 바울

5. 하나님 찾기 (관찰)
- 원주민들을 통해 특별한 보호를 해주심
- 독사에 물려도 살도록 보호해주심
- 부친과 병든 원주민들을 치유해주심

6. 인간 찾기 (관찰)
- 바울과 일행을 특별히 대우해주는 원주민들
- 독사에 물렸지만 죽지 않는 바울
- 보블리오의 부친을 위해 기도하고 안수하는 바울

7. 하나님 찾기 (해석) 
- 하나님은 바울과 일행을 보호해주셨다. 원주민들은 바울과 일행을 공격할 수 있었으나 특별한 대우를 한다. 하나님께서 그들의 마음을 열어주었을 것이다. 
- 가끔 나를 극진히(?) 대우해주는 사람들을 만날 때가 있다. 하나님께서 그의 마음을 움직여주셨을 것이다. 모든 것은 하나님의 은혜이다.

8. 인간(해석):
- 배에서 죽을뻔한 바울과 일행들은 원주민들의 대우에 안도했을 것이다. 
- 일행들은 바울이 독사에 물리고 죽지 않고, 원주민 보블리오의 부친과 많은 병든 사람들을 고치는 것을 보고 어떤 생각을 했을까?
- 이 사람은 진짜라는 생각을 했을 것 같다. 그러나 환경적 요인으로 용기를 내지 못해 예수님을 믿고 싶다는 말을 하지 못했던 사람도 있었을 것이다.

- 반면 현대에는 예수님을 알지만 부정하는 사람이 너무 많다. 그 사람들에게 복음을 어떻게 전할 수 있을까?
- 아무리 생각해도 과거와 같은 방법을 동일하게 하는 것 밖에 없는 것 같다. 삶의 모습으로 전도하고, 말로 전도하고, 돌아다니며 전도하는 것 등이다. 
- 방송, 문서 사역이 매우 중요해졌다, 그러나 바울과 같이 직접 필드에서 뛰는 전도도 함께 이루어져야 한다.
- 남청연은 필드에서 열심히 뛰는 선교 단체가 되길 소망한다.    

9. 적용(나): 
- 회원들을 위해 기도하고, 연락해야겠다. 노방전도 날씨가 춥지만 한 영혼을 바라며 계속 나가야겠다. 다음 해외 선교지를 계획해야겠다. 

10. 영적터치(단어/구절)
- 특별히

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-12-05', '사도행전', '28장 11~20절', '제목 없음', '(사도행전 28장)
11. 석 달 후에 우리가 그 섬에서 겨울을 난 알렉산드리아 배를 타고 떠나니 그 배의 머리 장식은 디오스구로라
12. 수라구사에 대고 사흘을 있다가
13. 거기서 둘러가서 레기온에 이르러 하루를 지낸 후 남풍이 일어나므로 이튿날 보디올에 이르러
14. 거기서 형제들을 만나 그들의 청함을 받아 이레를 함께 머무니라 그래서 우리는 이와 같이 로마로 가니라
15. 그 곳 형제들이 우리 소식을 듣고 압비오 광장과 트레이스 타베르네까지 맞으러 오니 바울이 그들을 보고 하나님께 감사하고 담대한 마음을 얻으니라
16.  우리가 로마에 들어가니 바울에게는 자기를 지키는 한 군인과 함께 따로 있게 허락하더라
17. 사흘 후에 바울이 유대인 중 높은 사람들을 청하여 그들이 모인 후에 이르되 여러분 형제들아 내가 이스라엘 백성이나 우리 조상의 관습을 배척한 일이 없는데 예루살렘에서 로마인의 손에 죄수로 내준 바 되었으니
18. 로마인은 나를 심문하여 죽일 죄목이 없으므로 석방하려 하였으나
19. 유대인들이 반대하기로 내가 마지 못하여 가이사에게 상소함이요 내 민족을 고발하려는 것이 아니니라
20. 이러므로 너희를 보고 함께 이야기하려고 청하였으니 이스라엘의 소망으로 말미암아 내가 이 쇠사슬에 매인 바 되었노라

