5.하나님 찾기(관찰)
- 모든 사람에게 하나님을 알 만한 능력을 주셨음
- 만물을 보면 하나님의 영원하심을 알 수 있음

6.인간 찾기(관찰)
- 바울이 수신자를 간절히 보기 원함
- 그 이유는 신령한 은사를 주어 견고하게 하기 위함
- 바울은 모든 이에게 빚진 자로서 로마에도 복음을 전하기를 원함
- 바울은 복음을 부끄러워하지 않음
- 왜냐하면 복음은 구원을 주시는 하나님의 능력이기 때문
- 복음은 믿음으로 믿음에 이르기 함
- 그것은 하나님의 의로 인함
- 하나님의 진노에 대해 말함

7.하나님 찾기(해석)
- 하나님은 모든 사람이 하나님을 찾고 알 수 있도록 창조하셨다.
- 하늘(해와 달과 별)과 땅과 바다, 모든 자연과 피조물과 이것들의 놀라운 순환을 보면,
- 영원하신 하나님의 속성을 느낄 수 있음
 
8.인간 찾기(해석)
- 바울은 로마의 신자들을 간절히 만나고 싶었는데,
- 그것은 성령님을 만나지 못한 이들에게 성령님을 만나고 은사를 받게 함으로 그들의 믿음을 더욱 견고히 하고 싶었기 때문이다
- 바울은 성경 지식을 일방적으로 전달하는 것이 아니라,
- 견고한 믿음을 바탕으로 서로에게 위로와 유익이 되기를 원함.

- 바울은 예수님께 받은 사명, 곧 복음을 전하는 일을 하는 자로서 자신은 모든 사람에게 빚진 자이기 때문에 로마에 가서도 복음을 전하겠다고 말함

- 복음에는 모든 믿는 자에게 구원을 주시는 하나님의 능력이 있기에 자신은 복음을 부끄러워하지 않는다고 말함
- 로마에 있는 자들은 예수님은 구주로 믿는 것을 공언하기에 매우 어려운 상황이었다.
- 강대국의 문화와 황제를 주인으로 섬겨야 하는 법 등이 이유였다.

- 복음에는 하나님의 의가 나타나기에 믿음으로 믿음에 이르게 하는데,
- 이 말은 사람의 의가 아니라, 하나님이 신자에게 의를 주신다는 것이다.
- 사람은 오직 은혜로 하나님께서 의롭다 칭하시고, 구원해 주시는 것이다,

- 하나님의 진노가 나타나는데, 이 진노는
- 불의로 진리(복음)을 막는 사람들의 모든 경건하지 않음과 불의에 대해 임한다.
- 하나님께서는 모든 사람들이 하나님을 알 수 있게 창조하셨고,
- 세상 만물을 보면 창조주가 있다는 것을 알 수 있게 하셨음 

9.적용(나) 
- 바울은 예수님께 받은 사명, 즉 복음을 전하는 일을 마치려 함에는 목숨도 아까워하지 않았다. 
- 바울의 열정을 본 받아야 한다.

- 불신자를 전도할 때 창조주를 생각해 보라고 하면 몇 주 안에 창조주가 있다는 결론을 얻었다고 말하고 한다.
- 그러나 그 창조주가 왜 하나님이냐고 반문하는 이가 있고, 이 과정은 매우 험난하기도 하다.
- 이럴 때 참으로 답답함을 많이 느끼는데,
- 그러나 창조주를 떠올리는 것도 하나님이 사람에게 심어 놓으신 것이며, 
- 하나님 바로 창조주라는 것을 믿게 하는 것도 하나님의 영역임을 기억하고
- 그저 복음을 전해야 할 것이다.

- 내게 필요한 것은 바울을 닮은 열정이다.

10.영적 터치(단어/구절)
  16   내가 복음을 부끄러워하지 아니하노니 이 복음은 모든 믿는 자에게 구원을 주시는 하나님의 능력이 됨이라 먼저는 유대인에게요 그리고 헬라인에게로다
  17   복음에는 하나님의 의가 나타나서 믿음으로 믿음에 이르게 하나니 기록된 바 오직 의인은 믿음으로 말미암아 살리라 함과 같으니라

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-12-09', '로마서', '1장 21~32절', '제목 없음', '(로마서 1장)
21. 하나님을 알되 하나님을 영화롭게도 아니하며 감사하지도 아니하고 오히려 그 생각이 허망하여지며 미련한 마음이 어두워졌나니
22. 스스로 지혜 있다 하나 어리석게 되어
23. 썩어지지 아니하는 하나님의 영광을 썩어질 사람과 새와 짐승과 기어다니는 동물 모양의 우상으로 바꾸었느니라
24. 그러므로 하나님께서 그들을 마음의 정욕대로 더러움에 내버려 두사 그들의 몸을 서로 욕되게 하게 하셨으니
25. 이는 그들이 하나님의 진리를 거짓 것으로 바꾸어 피조물을 조물주보다 더 경배하고 섬김이라 주는 곧 영원히 찬송할 이시로다 아멘
26. 이 때문에 하나님께서 그들을 부끄러운 욕심에 내버려 두셨으니 곧 그들의 여자들도 순리대로 쓸 것을 바꾸어 역리로 쓰며
27. 그와 같이 남자들도 순리대로 여자 쓰기를 버리고 서로 향하여 음욕이 불 일듯 하매 남자가 남자와 더불어 부끄러운 일을 행하여 그들의 그릇됨에 상당한 보응을 그들 자신이 받았느니라
28. 또한 그들이 마음에 하나님 두기를 싫어하매 하나님께서 그들을 그 상실한 마음대로 내버려 두사 합당하지 못한 일을 하게 하셨으니
29. 곧 모든 불의, 추악, 탐욕, 악의가 가득한 자요 시기, 살인, 분쟁, 사기, 악독이 가득한 자요 수군수군하는 자요
30. 비방하는 자요 하나님께서 미워하시는 자요 능욕하는 자요 교만한 자요 자랑하는 자요 악을 도모하는 자요 부모를 거역하는 자요
31. 우매한 자요 배약하는 자요 무정한 자요 무자비한 자라
32. 그들이 이같은 일을 행하는 자는 사형에 해당한다고 하나님께서 정하심을 알고도 자기들만 행할 뿐 아니라 또한 그런 일을 행하는 자들을 옳다 하느니라

