4. 주제 만들기:
진정한 할례 자는 누구인가?

5. 하나님 찾기 (관찰)
진정한 할례 자를 칭찬하시는 하나님 


6. 인간 찾기(관찰)
율법을 지키는 자와 왜곡하는 자 

7. 하나님 찾기(해석)
하나님은 유대인이나 이방인이나 공평하게 사랑하신다. 

누구나 진심으로 마음에 할례를 하며 하나님의 율법을 지키는 자를 기뻐하시고 구원의 기쁨을 주신다. 

8. 인간 찾기(해석)
유대인들의 구원의 상징인 "할례"를 그들은 단체적으로 굳게 믿고 민족주의 입장에서 큰 자부심을 품었었다. 

문제는 유대인 대부분은 율법의 하나인 할례를 행하는 것 이상으로 그 율법을 주신 하나님에 대한 존중 없음을 바울은 밝히고 있다. 

즉 외형적 의식은 행하나 율법의 하나님을 향한 마음의 순종은 하지 않는다는 것이다. 

율법을 지키지 않으면서 할례를 받는 것이 할례를 받지 않은 이방인들과 같고 도리어 율법에 순종하는 할례 받지 않은 이방인이 구원받을 것이라는 바울의 주장이다. 

이러한 부분을 생각할 때 구원을 받는 것은 민족적 외형적 표징이 아니라 중심을 보시는 하나님이신 것을 깨우친다.

9. 적용(구체적으로)
하나님에 대하여 아는 지식에 머무르지 않고 하나님을 만나는 종이 되도록 더욱 힘써야겠다. 

율법보다 크신 하나님의 품에 들어가 감사와 평안을 더욱더 누리기를 바라며 주님께 나아가야겠다.

10. 영적 터치 (단어 또는 구절)
29절: 할례는 마음에 할지니

11. 믿음과 회개 및 감사기도로 마무리', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-12-13', '로마서', '3장 11~20절', '율법의 행위로 그의 앞에 의롭다 하심을 얻을 육체가 없다.', '[롬3:11-20]
11 깨닫는 자도 없고 하나님을 찾는 자도 없고
12 다 치우쳐 함께 무익하게 되고 선을 행하는 자는 없나니 하나도 없도다
13 그들의 목구멍은 열린 무덤이요 그 혀로는 속임을 일삼으며 그 입술에는 독사의 독이 있고
14 그 입에는 저주와 악독이 가득하고
15 그 발은 피 흘리는 데 빠른지라
16 파멸과 고생이 그 길에 있어
17 평강의 길을 알지 못하였고
18 그들의 눈 앞에 하나님을 두려워함이 없느니라 함과 같으니라
19 우리가 알거니와 무릇 율법이 말하는 바는 율법 아래에 있는 자들에게 말하는 것이니 이는 모든 입을 막고 온 세상으로 하나님의 심판 아래에 있게 하려 함이라
20 그러므로 율법의 행위로 그의 앞에 의롭다 하심을 얻을 육체가 없나니 율법으로는 죄를 깨달음이니라

