8. 인간 찾기(해석)
사도 바울은 참된 믿음과 의가 무엇인지를 분명하게 밝히고 있다. 

하나님의 의를 올바로 이해하기 위해서는 먼저 하나님의 은혜를 깨달아야 한다. 

아브라함의 행위가 외형적으로는 충분히 자랑할 만한 의로움처럼 보일 수 있으나, 그것이 곧 하나님 앞에서의 의는 아니다. 

오히려 다윗처럼 허물이 많은 사람일지라도 하나님께서 그 죄를 사하여 주신다면 그는 참으로 복 있는 사람이다.

바울은 믿음의 선조인 아브라함과 다윗을 예로 들어 믿음과 의의 본질을 설명하면서, 그 말씀을 자신에게도 적용하고 있는 듯하다. 

그 역시 젊은 시절에는 하나님의 의를 이루겠다는 열심히 예수를 믿는 자들을 핍박했던 사람이었다. 

그러나 예수 그리스도를 만난 후 거듭난 바울은 헌신과 희생의 삶을 살았음에도 불구하고, 그조차 자신의 의로 내세우지 않는다.

그는 오직 죄인 된 자신을 사용하시는 하나님의 은혜에 감사할 뿐이며, 이러한 겸손한 감사의 태도가 바로 참된 믿음을 가진 사람의 모습임을 우리에게 일깨워 주고 있다.

