2025년 12월 20일
로마서 5장 01절~10절
1.1분기도
2. 본문 성경 읽기(3번)
3. 반복 단어 찾기(형광펜 사용 추천):
죽으셨도다/죽는/죽으심으로: 6절 7절 8절 10절
구원: 9절 10절
믿음으로: 1절 2절 
화목/화평: 1절 10절(2)
주 예수 그리스도/그의 아들: 1절 2절 6절 8절 9절 10절
하나님/하나님의 영광/하나님의 사랑: 1절 2절 5절 8절 10절  

4. 주제 만들기:
하나님과 화평을 누리자

5. 하나님 찾기 (관찰)
화평의 하나님
사랑의 하나님
우리를 위하여 돌아가신 예수님
이에 따라 사랑을 확증하신 하나님
다시 살아나신 주님
구원자가 되신 주님

6. 인간 찾기(관찰)
바울은 신자를 향하여 환란 중에도 포기하지 말고 천국 소망을 갖기를 당부하고 있다.
이에 따라 하나님과 화평을 누리기를 가르치고 있다.

7. 하나님 찾기(해석)
우리가 아직 죄인 되었을 때 우리를 위하여 예수님이 돌아가심으로 하나님 자신의 사랑을 확증하셨다. 

하나님은 사랑 그 자체이시고 영혼을 사랑하신다. 

그러므로 하나님은 누구든지 보혈의 피를 의지하여 구원받기를 원하신다. 

8. 인간 찾기(해석)
1절에 보면 신도들은 모두 하나님과 화평을 누릴 수 있다고 기록되어 있다. 

그런데 많은 신도는 불안과 걱정 속에 사는 것을 쉽게 볼 수 있다. 그것은 이 세상에 소망을 두고 있기 때문이다. 

3절에 보면 "환난 중에도 즐거워하나니 이는 환난은 이래를, 인내는 연단을, 연단은 소망을 이루는 줄 앎이로다." 기록되어 있다. 

누구나 세상에서 살 때 크고 작은 환난은 있다. 믿는 자의 특권은 소망을 붙잡고 하나님과 화평을 누릴 수 있다는 사실이다. 

며칠 전 장례식장 다녀왔다. 중년 된 아들을 암으로 먼저 떠나보낸 권사님 한 분과 짧은 만남을 가졌다. 

아들을 먼저 보낸 노모인지라 개인적으로 많이 위로해드리고 싶었다. 

그런데 도리어 그 권사님은 천국 소망을 확실하게 믿기에 도리어 환한 미소로 하나님께 아들이 암 투병 중에 큰 통증 없이 천국으로 인도하신 하나님께 영광을 올리고 계셨다. 

그 권사님은 큰 환난을 만났지만, 천국 소망을 붙잡음으로 평안의 복을 체험하고 계신 것이다. 

하나님 말씀은 기능적 문자를 초월하여 우리 삶을 윤택하게 살도록 역사하시는 생명의 능력 그 자체인 것을 믿는다.

9. 삶의 적용(구체적으로)
하나님과 더불어 더욱 화평을 누려야겠다. 

오늘 밤에 따로 시간을 내어 마음에 큰 평안을 누리기 위한 기도를 올려야겠다.

10. 영적 터치 (단어 또는 구절)
하나님과 화평을 누리자

11. 믿음과 회개 및 감사기도로 마무리', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-12-20', '로마서', '5장 11~21절', '제목 없음', '(로마서 5장)
11. 그뿐 아니라 이제 우리로 화목하게 하신 우리 주 예수 그리스도로 말미암아 하나님 안에서 또한 즐거워하느니라
12.  그러므로 한 사람으로 말미암아 죄가 세상에 들어오고 죄로 말미암아 사망이 들어왔나니 이와 같이 모든 사람이 죄를 지었으므로 사망이 모든 사람에게 이르렀느니라
13. 죄가 율법 있기 전에도 세상에 있었으나 율법이 없었을 때에는 죄를 죄로 여기지 아니하였느니라
14. 그러나 아담으로부터 모세까지 아담의 범죄와 같은 죄를 짓지 아니한 자들까지도 사망이 왕 노릇 하였나니 아담은 오실 자의 모형이라
15. 그러나 이 은사는 그 범죄와 같지 아니하니 곧 한 사람의 범죄를 인하여 많은 사람이 죽었은즉 더욱 하나님의 은혜와 또한 한 사람 예수 그리스도의 은혜로 말미암은 선물은 많은 사람에게 넘쳤느니라
16. 또 이 선물은 범죄한 한 사람으로 말미암은 것과 같지 아니하니 심판은 한 사람으로 말미암아 정죄에 이르렀으나 은사는 많은 범죄로 말미암아 의롭다 하심에 이름이니라
17. 한 사람의 범죄로 말미암아 사망이 그 한 사람을 통하여 왕 노릇 하였은즉 더욱 은혜와 의의 선물을 넘치게 받는 자들은 한 분 예수 그리스도를 통하여 생명 안에서 왕 노릇 하리로다
18. 그런즉 한 범죄로 많은 사람이 정죄에 이른 것 같이 한 의로운 행위로 말미암아 많은 사람이 의롭다 하심을 받아 생명에 이르렀느니라
19. 한 사람이 순종하지 아니함으로 많은 사람이 죄인 된 것 같이 한 사람이 순종하심으로 많은 사람이 의인이 되리라
20. 율법이 들어온 것은 범죄를 더하게 하려 함이라 그러나 죄가 더한 곳에 은혜가 더욱 넘쳤나니
21. 이는 죄가 사망 안에서 왕 노릇 한 것 같이 은혜도 또한 의로 말미암아 왕 노릇 하여 우리 주 예수 그리스도로 말미암아 영생에 이르게 하려 함이라

