5. 하나님 찾기 (관찰)

6. 인간 찾기 (관찰)
- 선을 행하는 자신에게 악한 마음도 함께 있다는 것을 깨닫는 바울
- 예수 그리스도를 통해 하나님께 감사드리는 바울

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 바울은 사명을 다하는 자신에게 악한 마음도 있다는 것을 깨달았다.
- 우리에게 큰 영향을 미치고 있는 사도 바울도 끊임없이 악과 싸웠음을 의미한다.

- 우리의 마음에서 이루어지는 생각들이 죄로 이어지는 경우가 많다. 그러므로 우리는 생각에서 비롯되는 죄를 끊어버리기 위해 스스로 통제할 수 있는 능력을 갖추어야 한다.
- 그것은 나의 힘으로, 의지로 되는 것은 아니고, 예수님의 보혈의 피로 가능하다.
- 때론 의지는 있지만 육신이 연약하여 넘어질 때가 있다.
- 넘어진 것에 좌절하기 보단 예수님께서 우리를 위해 십자가를 지신 것을 생각하고, 십자가를 통해 언제든 다시 일어설 수 있음을 믿으며, 죄와 끝까지 싸워야 한다.

- 사탄은 우리를 넘어뜨리고 싶어 한다. 우리는 그것에 속으면 안 된다. 

9. 적용(나): 
- 죄에 넘어지지 않도록 생각을 잘 다스려야겠다. 

