우리: 31(3), 32(2), 34, 35, 36,37(2), 39(2)
아들: 32(2)
예수: 34, 39
사랑: 35, 37, 39

4.주제 만들기: 끊을 수 없는 하나님의 사랑

5.하나님 찾기(관찰)
- 자기 아들을 아끼지 아니하시고 우리 모든 사람을 위하여 내주심
- 다시 살아나신 예수님은 하나님 우편에 계시며 우리를 위하여 간구하심

6.인간 찾기(관찰)
- 하나님이 우리를 위하시니 우리를 대적하거나 고발하거나 정죄할 수 없음
- 그리스도의 사랑에서 우리를 끊어낼 자가 없음
- 종일 죽임을 당하게 되며 도살당할 양 같이 여김을 받더라도 우리를 사랑하시는 이로 말미암아 모든 것을 넉넉히 이길 수 있다
- 어떤 강력한 피조물도 우리 주 그리스도 예수 안에 있는 하나님의 사랑에서 우리를 끊을 수 없다

7.하나님 찾기(해석)
- 하나뿐인 아들을 내어주실 정도로 하나님은 우리를 사랑하신다
- 다시 살아나신 예수님은 살아계실 뿐 아니라 하나님 우편에서 우리를 위하여 간구하신다
- 예수님도 성령님도 우리를 사랑하시고 우리를 위하여 기도해 주시니 우리가 두려워할 것이 없다
- 비록 우리가 누군가에게 핍박을 당하더라도 우리가 이겨낼 수 있는 것은 우리를 뜨겁게 사랑하시는 하나님께서 우리를 도우시고 구원하시기 때문이다. 
- 뜨거운 하나님의 사랑은 그 무엇으로도 끊을 수 없다

8.인간 찾기(해석)
- 하나님이 우리를 위하시니 그 어떤 피조물도 우리를 정죄할 수 없다
- 자기 아들을 내어주실 정도로 우리를 사랑하시니 그 어떤 존재가 우리를 고발하고 정죄하더라도 하나님은 자녀된 우리를 용서하시고 돌보실 것이 확실함
- 우리는 극한의 핍박 속에 살 것이다 
- 그러나 우리는 이 어려움을 이겨낼 수 있을 뿐 아니라 넉넉히 이겨낼 것인데, 그 이유는 우리를 뜨겁게 사랑하시는 하나님께서 우리를 도우시고 구원하시기 때문이다.
- 그 어떤 두려운 일과 존재일지라도 우리 주 그리스도 예수 안에 있는 하나님의 사랑에서 우리를 끊을 수 없다 

9.적용(나) 
- 인간들의 삶 가운데는 누구에게나 생사화복과 생로병사, 통과의례가 있고, 온갖 오해와 갈등, 모함, 그리고 핍박이 있을 수 있다.
- 이런 일들로 인해 괴롭고 지쳐 아무것도 할 수 없을 때가 오면, 우리는 예수님을 기억하고 바라봐야 한다.
- 하나님 우편에서 우리를 위해 간구하시는 분, 예수님이 계시니 우리는 힘을 내어 일어설 수 있다.
- 또한 이 예수님 안에서 우리를 향하신 하나님의 사랑을 기억하자
- 만약 우리가 너무나 힘겨워 기억하지 못하더라도 우리는 결국 예수님의 기도와 하나님의 사랑으로 말미암아 일어서게 됨을 경험하게 될 것이다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

