사도 바울은 큰 사랑을 지닌 사람이 분명하다.

. 자신의 친척들이 구원만 받을 수 있다면, 자신은 지옥에 가는 것도 불사하겠다고 고백했다. 

이 모습은 죄를 범한 자기 백성에게 하나님께서 심판을 내리시려 할 때, “차라리 내 이름을 생명책에서 지워 주십시오”라고 간구했던 모세의 모습과 매우 닮아 있다.


그러나 우리의 대장이신 예수님께서는 그것을 말로만 하신 것이 아니라 직접 실행하신 분이십니다. 죄 없으신 분께서 친히 십자가를 지셨습니다. 그러한 독생자를 아낌없이 내어 주신 하나님께서 우리를 자녀 삼아 주셨다.


하지만 그 은혜에는 한 가지 조건이 있다. 아브라함의 씨라고 해서 모두가 해당되는 것이 아니라, 이스마엘이 아니라 사라를 통해 태어난 이삭의 후손이어야 한다는 것입니다. 

이는 하나님께서 아브라함에게 약속하신 말씀 그대로이다.

믿는 자들을 끝까지 지켜주신다는 하나님의 약속의 말씀때문에 오늘도 평안 가운데 사는 기쁨이 있다.

