- 하고자 하시는 자를 긍휼히 여기시고 하고자 하시는 자를 완악하게 하심

6.인간 찾기(관찰)
- 그러면 하나님은 어찌하여 허물하시느냐 누가 그 뜻을 대적하느냐 물을 수 있으나,
- 지음 받은 인간이 하나님께 반문할 수는 없다

7.하나님 찾기(해석)
- 하나님은 구원의 통로로 사용할 사람을 선택하신다.
- 이 택하심은 에서와 이삭이 리브가의 배에 있을 때에 이루어졌는데,
- 이것으로 보아 하나님의 택하심은 그 사람의 선한 행위나 악한 행위가 근거가 되는 것이 아니라 전적으로 하나님의 부르심에 있는 것을 알 수 있다.
- 하나님의 뜻은 사람의 행위가 아니라 하나님의 부르심과 역사하심으로 말미암아 이루어지는 것이다.
- 하나님께서는 완악한 자도 긍휼히 여기실 자도 선택하시는데 이것에 대해 피조물인 우리 인간이 반문할 수는 없는 것이다.

8.인간 찾기(해석)
- 하나님께서 자기 뜻대로 선택하시고 선과 악으로 사용하신다면 어찌 사람을 허물하시느냐, 또는 누가 하나님의 뜻에 대적하겠느냐 반문할 수 있으나,
- 바울은 피조물과 창조주의 관계를 물건과 물건을 만든 사람으로 비유하며, 지음을 받은 물건이 지은 자에게 왜 나를 이렇게 만들었느냐 말할 수 있느냐 물으며 독자에게 창조주 앞에서 겸손할 것을 강조함

9.적용(나) 
- 내가 극한 악으로 달음박질하도록 내버려 두지 않으시고, 내게 찾아오시고 변화시키신 하나님께 감사와 찬양을 드린다.
- 하나님께서는 또 다른 나와 같은 자를 찾고 계신다.
- 주님의 소원에 동참하는 자가 돼야한다.

