하나님의 의: 3절 4절 10절
시인: 9절 10절 
구원: 9절 10절
     
4. 주제 만들기:
하나님의 의와 세속적인 의

5. 하나님 찾기 (관찰)  
바르게 인도하시는 하나님
구원의 하나님 

6. 인간 찾기 (관찰)
자기 뜻대로 사는 인간
예수를 주로 시인하면 구원받는 인간 


7. 하나님 찾기(해석)
하나님은 지금도 마찬가지로 모든 인간이 구원받기를 원하신다. 하나님 자녀로 거듭나서 하나님의 의를 이루며 풍요롭게 살기를 바라신다. 

8. 인간 찾기(해석)
이스라엘 백성은 하나님에 대한 열심은 있었으나, 올바른 뜻을 따르지 않았다. 

그 이유는 자기 의, 곧 자신의 유익을 먼저 세웠기 때문이다. 이는 처음부터 잘못된 설계도와 같다고 할 수 있다. 

오늘날의 신도들 또한 마찬가지로, 교회 안에서 열심히 봉사하면서도 그 이면에 자신의 명예나 의를 위한 숨겨진 동기가 있을 수 있음을 점검해 보아야 한다.

그렇다면 올바르게 하나님의 의를 행하는 방법은 무엇일까? 아마도 9절과 10절의 말씀대로, 하나님의 자녀 됨이라는 정체성을 인정받는 것에서부터 시작되는 것 같다. 

이는 곧 구원의 확신의 문제다. 그 방법은 진심으로 예수님을 구원자로 마음으로 믿고, 입술로 고백하는 것이다.


여기서 ‘시인한다’는 의미는 결코 가볍지 않다. 당시 로마 제국의 폭군 네로 황제는 사자들을 풀어놓고, 예수를 시인하면 사자 밥이 되는 형벌을 내렸으며, 반대로 부인하면 살려주었다. 

이러한 역사적 배경을 생각해 볼 때, 예수를 믿는다는 것은 나의 육체적 이익을 위하여 믿는 것이 아니라, 목숨을 걸고 하나님의 뜻을 따르겠다는 모든 고백을 내포하고 있다.


이러한 믿음을 갖기 위하여 고군분투하는 신자들이라면, 일상생활 속에서도 세상의 가치에서 벗어나 온전한 진리의 길로 나아가는 바른 선택을 하게 될 것이다. 

그 결과, 하나님 앞에서뿐만 아니라 세상 속에서도 칭찬받는 좋은 신앙인이 될 것이다.

9. 삶의 적용(구체적으로)
하나님이 기뻐하시는 일들을 연구하고 세상의 의에 속한 일들에 대하여 무관심 갖는 훈련을 해야겠다.

10. 영적 터치 (단어 또는 구절)
 10절:시인하여 구원에 이르느니라

11. 믿음과 회개 및 감사기도로 마무리', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-01-02', '로마서', '9장 21~33절', '그릇을 만드신 하나님', '[롬9:21-33]
21 토기장이가 진흙 한 덩이로 하나는 귀히 쓸 그릇을, 하나는 천히 쓸 그릇을 만들 권한이 없느냐
22 만일 하나님이 그의 진노를 보이시고 그의 능력을 알게 하고자 하사 멸하기로 준비된 진노의 그릇을 오래 참으심으로 관용하시고
23 또한 영광 받기로 예비하신 바 긍휼의 그릇에 대하여 그 영광의 풍성함을 알게 하고자 하셨을지라도 무슨 말을 하리요
24 이 그릇은 우리니 곧 유대인 중에서뿐 아니라 이방인 중에서도 부르신 자니라
25 호세아의 글에도 이르기를 내가 내 백성 아닌 자를 내 백성이라, 사랑하지 아니한 자를 사랑한 자라 부르리라
26 너희는 내 백성이 아니라 한 그 곳에서 그들이 살아 계신 하나님의 아들이라 일컬음을 받으리라 함과 같으니라
27 또 이사야가 이스라엘에 관하여 외치되 이스라엘 자손들의 수가 비록 바다의 모래 같을지라도 남은 자만 구원을 받으리니
28 주께서 땅 위에서 그 말씀을 이루고 속히 시행하시리라 하셨느니라
29 또한 이사야가 미리 말한 바 만일 만군의 주께서 우리에게 씨를 남겨 두지 아니하셨더라면 우리가 소돔과 같이 되고 고모라와 같았으리로다 함과 같으니라
30 그런즉 우리가 무슨 말을 하리요 의를 따르지 아니한 이방인들이 의를 얻었으니 곧 믿음에서 난 의요
31 의의 법을 따라간 이스라엘은 율법에 이르지 못하였으니
