5. 하나님 찾기 (관찰)
- 이스라엘 백성을 버리지 않으심
- 은혜로 택하심
- 혼미한 심령과 보지 못할 눈과 듣지 못할 귀를 주심

6. 인간 찾기 (관찰)
- 하나님께서 이스라엘 백성을 버리지 않으셨다고 말하는 바울
- 은혜로 택하심을 받은 자들이 있음을 알려주는 바울

7. 하나님 찾기 (해석) 
- 하나님은 우리를 버리지 않으셨다. 
- 그 분은 직접 인간의 몸으로 이 땅에 오셔서, 친히 화목 제물이 되시고, 십자가에 매달려 장사된 후, 사흘 만에 다시 태어나 하늘에 올라가셨다.
- 여기서 그치지 않고 하나님은 우리를 택하셨다.
- 이 모든 것은 하나님의 은혜 아니고선 설명할 수 없다.
- 이 사실을 믿는 것 또한 하나님의 은혜이다. 

8. 인간(해석):
- 예수님을 믿지 않고, 예수님을 들어도 부정하는 사람이 참 많다.
- 그럴 때 좌절감이 들기도 하다. 요즘은 다수가 교회를 욕하고, 다수가 예수를 믿는다는 것을 허상을 쫓는다고 말한다.
- 그러나 우리는 은혜로 하나님이 살아계심을 믿는다.
- 그리고 믿음의 동역자를 만나 서로 위로하고, 격려하고, 같은 마음으로 소망을 품으며, 힘을 낸다.
- 우리는 하나님의 택하심을 받아 남은 자들이다.
- 죽는 날까지 하나님의 사랑을 전하며 단, 한 영혼이라도 구원 받을 수 있도록 최선의 노력을 다해야 한다.

9. 적용(나): 
- 남청연이 바른 길로 인도하신 하나님께 감사하다. 하나님의 사랑을 전할 수 있도록 우리의 지경이 넓어지길 기도해야겠다.(대교 전도, 일본 선교)

