- 구원받은 신자는 하나님의 구원하심을 판단하는 것이 아니라 그저 감사해야 한다.
- 우리는 하나님이 창조하셨고 통치하시며 심판 후에 하나님과 영원히 살 것을 기억해야 한다.
 
