7. 하나님 찾기(해석)
하나님은 자녀를 택하여 부르실 때 그냥 부르지 않으시고 각자 필요한 은사를 주신다. 

그 이후에 하나님은 그에 따르는 후회가 없으시다고 하셨다. 내가 선교사로 부름을 받고 헌신하며 사역한 지 벌써 17년이 다 되어간다. 

나 자신을 뒤돌아보면 하나님 앞에 부끄러울 정도로 후회되는 일들이 많은데도 불구하고 하나님은 나로 인하여 후회하지 않으신다고 하니 얼마나 감사한 일인가? 

모든 미래를 아시는 하나님께 온전히 붙어사는 것이 얼마나 큰 복인지 실감하게 된다. 때때로 그 가지가 바람과 풍파로 인하여 많이 부서지고 볼품없어 보이더라도 하나님께 붙어 있는 그것만으로도 이미 축복받은 생명의 아름다운 가지이다.

 
8. 인간 찾기(해석)
하나님의 본심은 접붙임 받은 이방 민족뿐만 아니라 일시적으로 외면 받는 이스라엘 백성 포함하여 모두 회개하고 하나님께로 돌아와서 구원받기를 원하심을 알 수 있다. 

26절에 “온 이스라엘이 구원을 받으리라” 기록되어 있다. 인자하시고 긍휼함이 많으신 하나님을 더욱 경외하는 삶을 사는 것이 인간의 기본적 태도라 여겨진다. 

또한 신자들도 또한 모든 영혼을 사랑하는 마음을 가지는 것이 하나님이 원하시는 바이다.

9. 삶의 적용(구체적으로)
인자가 많으시고 긍휼하신 하나님을 더욱 찬양해야겠다. 
 
10. 영적 터치 (단어 또는 구절)
 29절: 부르심에 후회하심이 없느니라

11. 믿음과 회개 및 감사기도로 마무리', 0, true);

