- 특별히 육적인 필요도 중요하지만 중보 기도를 요청했는데, 이 시대의 선교사님들이 생각난다.
- 오늘날 선교를 함에 있어서 많은 어려움이 있다.
- 문화적 장벽, 영적 전쟁, 언어의 한계, 외로움과 경제적인 문제 등 복음의 전초기지에서 고군분투하고 있다.
- 우리 남청연의 사역도 마찬가지이다. 
- 많은 어려움 가운데 놓여있다. 특히 요즘은 영적 전쟁이 심한 것 같다.
- 우리의 사역이 지경이 넓어지니 기도가 더욱 필요한 요즘이다.
- 남청연 회원 모두가 같은 마음을 품고 중보하길 소망해본다.

9. 적용(나): 
- 선교사님들을 위한 기도를 꾸준히 해야겠다.
- 남청연이 같은 마음으로 중보하고 동역하는 선교 단체가 되길 기도해야겠다.

10. 영적터치(단어/구절)
- 섬김

