7. 하나님 찾기 (해석)
- 하나님의 뜻과 계획을 우리는 감히 알 수 없다. 
- 하나님은 인간의 몸으로 이 땅에 오셔서 십자가를 지셔서 우리를 구원하셨다. 
- 예수 그리스도를 통해 복음을 완성하신 것이다.
- 이 복음은 우리를 구원할 뿐 아니라 우리를 견고케 한다.
- 하나님은 우리를 너무 사랑하신다.

8. 인간(해석):
- 바울은 복음으로 견고해질 우리의 삶을 언급하며 편지를 마쳤다.
- 복음은 우리를 견고케 할 것이다.
- 그렇다고 우리의 삶 가운데 고난이 없을까? 그것은 절 때 아니다. 
- 언제, 어느 순간, 어떻게 고난이 다가올지 모른다.
- 그렇다면 당시 이름 모를 수 많은 제자들은 고난이 없었을까?
- 오히려 우리보다 더 많았을 것이다. 
- 나의 신앙의 행태와 모습을 반성한다. 
- 죽을 각오로 예수를 믿는 수많은 사람들이 있다.
- 내 안에 이런 견고한 믿음이 있는가? 

9. 적용(나): 
- 어떤 상황에서도 흔들리지 않는 견고한 믿음이 내 안에 주어지길 소망한다.
- 우리를 견고케하는 복음을 꾸준히 전해야겠다.

