4. 주제 만들기:
하나님의 일과 영적 비례관계


5. 하나님 찾기 (관찰) 
가르치시는 성령님
은혜를 공급하시는 하나님

6. 인간 찾기 (관찰)
사람의 영으로는 하나님의 일을 알 수 없다.
하지만 하나님의 영을 품은 사람은 하나님의 일을 알 수 있다. 

7. 하나님 찾기(해석)

8. 인간 찾기(해석)
그리스도의 마음을 가진 사람은 영적인 사람이다. 

그들은 세상에서 말하는 지혜와 다르다. 세상의 성공과 하나님이 추구하시는 목적은 처음부터 많이 달라 있었다.

성경에 나오는 수많은 위인들은 대부분 세상 사람들의 눈에 미련하고 어리석게 보였다. 

가령 노아는 바다에 방주를 만들지 않고 산에 그 배를 지었다. 

세상 사람들은 그를 향해 미친 사람 취급을 하였다.
하지만 결론적으로 노아는 하나님의 영을 받들어 큰 배를 지었고, 나중에 보니 그 배는 구원의 배였다. 

이 신비로운 역사는 세상의 눈으로는 도저히 이해할 수 없을 것이다.

신약에 보면 많은 주님의 제자들이 목숨을 걸고 미련한 방법으로 전도를 하였다. 

그로 인하여 그들은 대부분 순교를 당했다. 

그로 인해 주변 사람들로부터 어리석은 사람들이라 조롱을 당하였다.

지금 이 시대에도 부귀영화를 포기하고 어리석은 방법으로 삶을 드려 선교하는 많은 주의 그리스도인들이 있다. 

이러한 어리석게 보이는 일들에 대하여 존경하고, 함께 그 일에 기꺼이 기쁨으로 동참하는 이들도 많다.

왜 그럴까? 그것은 성령님 안에서 한 영으로 서로 신비로운 세계를 체험했기 때문일 것이다. 

이러한 사람들의 공통점은 세상의 소리보다 천국의 소리에 귀를 기울이는 것이다. 

이들은 어리석음을 포장한 진정으로 똑똑한 그리스도의 마음을 가진 사람들이다.

9. 삶의 적용(구체적으로)
하나님의 마음을 품고 받은 사명 잘 감당해야겠다. 그러기 위하여 하나님 말씀을 더욱 깊게 묵상해야겠다.
 

10. 영적 터치 (단어/구절)
