5.하나님 찾기(관찰)
- 어둠에 감추인 것들을 드러내고 마음의 뜻을 나타내실 것이다.

6.인간 찾기(관찰)
- 맡은 자들에게 구할 것은 충성이다.
- 주께서 오시기까지 아무 것도 판단하지 말라.
- 교만한 마음을 가지지 말라

7.하나님 찾기(해석)
- 하나님은 각 사람의 모든 것을 알고 계시기 때문에 심판 날에 어둠에 감추인 것들을 드러내고 마음의 뜻을 나타내실 것이다.
- 사람이 감춘 것도 드러내어 심판 하시고, 마음의 뜻도 나타내어 심판하실 것이다.

8.인간 찾기(해석)
- 맡은 자들에게 구할 것은 충성이다. 리더는 하나님과 교회에 충성하는 자가 돼야 한다.
- 신자는 교회에서 사람을 판단해서는 안 된다. 판단은 신자의 몫이 아니라 하나님의 몫이다.
- 믿음과 능력이 생겼다고 교만해서는 안 된다. 믿음과 능력은 선물로 주어진 것이지 자기가 스스로 만들어낸 것이 아니기 때문이다.
- 교회는 스스로 높아진 마음 때문에 사람을 판단하고 정죄하게 되는데 이것은 교회를 분열시키는 악한 씨앗이다.

9.적용(나) 
- 신자의 겸손과 교만은 종이 한 장 차이만큼 가깝다. 잠깐 정신을 놓으면 겸손에서 교만으로 넘어간다. 스스로 교만한 상태인지 점검하기도 어렵다.
- 어쩌면 겸손과 교만은 동전의 양면이기도 하다. 신자는 겸손하면서 동시에 교만할 수도 있다.
- 우리는 이것을 기억하고 늘 점검하고 주님 앞에 납작 엎드린 자세를 유지하고자 노력해야 한다.  

