4.주제 만들기: 음행하는 자들과 사귀지 말라

5.하나님 찾기(관찰)
- 세상 죄인들을 심판하신다.

6.인간 찾기(관찰)
- 고린도교회에 아버지의 아내를 취한 자가 있음을 들음.
- 고린도교회는 이런 자를 교회에서 쫓아내지 않음
- 이런 자는 사탄에게 내주어 육신은 멸하고 영은 구원받게 하려는 것
- 적은 누룩이 온 덩어리에 퍼지는 것을 알아야 함
- 새 덩어리가 되기 위해 묵은 누룩을 버려야 함
- 음행하는 자들과 사귀지 말라고 했으나 그것이 이 세상 사람들을 도무지 사귀지 말라 한 것은 아님
- 그렇게 하려면 세상 밖으로 나가야 함
- 다만 교회 안에서 형제라는 자가 음행하거나 탐욕을 부리거나 우상 숭배를 하거나 모욕하거나 술 취하거나 속여 빼앗거든 사귀지도 말고 그런 자와는 함께 먹지도 말고 교회에서 쫓아내야 한다.

7.하나님 찾기(해석)
- 세상의 죄인들은 하나님께서 심판하신다.
- 그러나 교회의 형제 중에서 음행 등의 죄를 행한 자와는 교제를 하지 말고, 또한 교회에서 쫓아내야 한다.
- 그래야만 성도와 교회가 거룩하게 유지된다. 

8.인간 찾기(해석)
- 고린도교회에 음행의 죄를 가볍게 보거나 관대하게 생각하는 경향이 있었던 것으로 보임
- 교회에 음행이 만연하여 당시 로마 사회에서도 일어나지 않을 계모에 대한 음행까지 일어났음을 지적함
- 교회에서는 이런 자를 징계하고 추방했어야 하지만, 그런 절차가 없었던 것으로 보임
- 바울은 이런 자를 사탄에게 내주어야 한다는 말로 교회에서 추방하여 세상으로 쫓아내야 함을 말함
- 그렇게 함은 먼저 죄를 돌아보고 회개할 기회를 주는 것이고, 회개를 통해 심판의 날 구원받게 할 수 있다고 말하는 것
- 이런 자를 교회에 그대로 두면 적은 누룩이 온 덩어리에 퍼지는 것과 같이 음행이 교회 전체에 퍼질 수 있다고 말함
- 그리스도의 희생으로 거듭난 신자와 교회는 죄를 버리고 거룩하게 살아야 함을 가르침
- 세상에는 음행하는 자들이나 탐하는 자들이나 속여 빼앗는 자들이나 우상 숭배하는 자들이 너무나 많아서 세상에서는 이런 자들을 사귀지 않고 살아갈 수는 없다고 말함으로써 세상 사람들과는 사귈 수 있음을 피력함
- 세상 사람들과 달리 교회 안에서 형제라 불리는 자가 음행 등의 죄를 지을 경우에는 그런 자와는 교제도 하지 말고 교회에서 쫓아내야 한다.
- 왜냐하면 이렇게 징계해야 다른 성도들이 그들에게 오염되지 않고 성도와 교회가 거룩하게 유지될 수 있기 때문이다.  
   
9.적용(나) 
- 교회는 사랑의 공동체이지만, 위와 같은 죄를 징계 없이 사랑으로 감싸줄 수는 없다.
- 징계 없는 사랑은 방종이며, 교회를 오염시키는 일이다.
- 교회는 사랑과 용서와 관용에 대하여 오해해서는 안 된다.
- 많은 신자들이 이 부분을 오해하여 죄를 징계하지 못하고 끙끙 앓다가 죄 짓는 이들과 함께 하는 경우가 종종 있는데, 이것은 개인과 교회를 오염시키는 위험한 생각이다.
- 교회에서 신자라는 사람이 위 구절과 같은 죄를 범할 경우에는 반드시 그를 징계해야 한다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-01-30', '고린도전서', '6장 1~10절', '제목 없음', '[고전6:1-10]
1 너희 중에 누가 다른 이와 더불어 다툼이 있는데 구태여 불의한 자들 앞에서 고발하고 성도 앞에서 하지 아니하느냐
2 성도가 세상을 판단할 것을 너희가 알지 못하느냐 세상도 너희에게 판단을 받겠거든 지극히 작은 일 판단하기를 감당하지 못하겠느냐
3 우리가 천사를 판단할 것을 너희가 알지 못하느냐 그러하거든 하물며 세상 일이랴
4 그런즉 너희가 세상 사건이 있을 때에 교회에서 경히 여김을 받는 자들을 세우느냐
5 내가 너희를 부끄럽게 하려 하여 이 말을 하노니 너희 가운데 그 형제간의 일을 판단할 만한 지혜 있는 자가 이같이 하나도 없느냐
6 형제가 형제와 더불어 고발할 뿐더러 믿지 아니하는 자들 앞에서 하느냐
7 너희가 피차 고발함으로 너희 가운데 이미 뚜렷한 허물이 있나니 차라리 불의를 당하는 것이 낫지 아니하며 차라리 속는 것이 낫지 아니하냐
8 너희는 불의를 행하고 속이는구나 그는 너희 형제로다
9 불의한 자가 하나님의 나라를 유업으로 받지 못할 줄을 알지 못하느냐 미혹을 받지 말라 음행하는 자나 우상 숭배하는 자나 간음하는 자나 탐색하는 자나 남색하는 자나
10 도적이나 탐욕을 부리는 자나 술 취하는 자나 모욕하는 자나 속여 빼앗는 자들은 하나님의 나라를 유업으로 받지 못하리라

