4. 주제만들기

5. 하나님 찾기 (관찰)

6. 인간 찾기 (관찰)
- 불의한 일이 있을 때 성도 안에서 해결하지 않고 불의한 사람들 앞에서 고발하냐고 묻는 바울
- 믿는 사람들이 지혜롭게 일을 해결하길 바란 바울
- 서로 고발한다는 것은 실패를 의미하며 억울한 일을 당해주고 서로 속아주지 못하냐는 바울
- 불의한 사람은 하나님 나라의 유업을 받지 못할 것이라 말하는 바울

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 오늘 본문에서 바울의 권면은 도전이 되는 말씀이다.
- 공동체 안에서 분쟁이 일어났을 때 이를 어떻게 해결해야 하는지 분명히 알 수 있다.
- 첫째, 어려움이 있더라도 지혜롭게 해결해야 한다.
- 둘째, 서로의 입장차로 해결되지 않는다면 지혜로운 일꾼에게 도움을 얻어야 한다. 사역자들에게 도움을 구하는 것이 좋다.
- 셋째, 그럼에도 해결되지 않을 수 있다. 그럴 땐 억울함을 감수하여야 한다.
- 내 안에 남아있는 분노를 하나님께 맡기고, 공동체 안에서는 더 이상 불미스러운 일이 있어선 안된다.

- 세 번째 방식은 많은 사람들에게 공통적인 어려움일 것이다. 
- 나 또한 그렇다. 그러나 우리는 억울함, 분노를 뛰어넘어야 한다.
- 모든 상황을 아시는 하나님을 의지하자. 그 분께 모든 것을 맡겨드리자.
- 그리고 억울함을 감당하자.
- 모두에게 귀한 도전이 될 것이다.

9. 적용(나): 
- 억울한 일이 생기지 않길 바라지만 그런 상황에서 억울함을 감당할 수 있는 믿음이 생기길 기도한다.

10. 영적터치(단어/구절)
