2026년 02월 4일
고린도 전서 7장 31절~40절
1.1분기도
2. 본문 읽기(3번)
3. 반복 단어 및 같은 의미
기쁘시게/기쁘게: 32절 34절
결혼: 33절 34절 38절(2)
약혼녀: 36절(2)
주: 32절 34절 35절 39절
