- 사도 바울은 자신의 행동으로 우리에게 보여주었다.
- 자신이 누릴 수 있는 권리를 내려놓고, 오직 복음을 위해 소망을 쫓아가는 삶.
- 많은 인기와 명성, 명예를 누릴 수 있음에도, 호의를 받지 않고 낮은 곳에서 섬겼던 삶, 이런 삶을 우리는 본 받아야 한다.
- 호의는 누구나 받고 싶어 한다. 그것을 억제하고, 거절할 수 있는 마음이 우리 안에 있어야 할 것이다.

