8. 인간(해석):
- 과거나 현대나 마찬가지로 우상숭배, 음행, 하나님을 시험하거나 원망하는 행동은 우리 가운데 여전히 존재한다.
- 구약의 이스라엘 백성의 죄는 가차 없이 죽음으로 이어졌지만 우리는 예수님을 통해 죽음에서 벗어나 생명의 삶을 살아갈 수 있게 되었다.
- 그럼에도 우리 주변에는 우상숭배와 음행, 하나님을 시험하고픈 마음과 하나님을 향한 원망을 하게 만드는 일들이 수없이 존재하고 있다. 
- 우리는 이런 어둠 가운데에서 빛이신 예수님을 바라보며 이겨낼 수 있는 훈련이 되어야 한다.
- 불행하게도 예수를 믿는다고 모두 복을 받거나 모든 일이 잘 되는 것이 아니다.
- 우리나라에 유명한 목사님들 중 몇 분은 육체의 고통으로 돌아가신 일도 있다. 그 분들이 영성이 없어서? 능력이 없어서 일까? 절 때 아니다. 
- 고통과 고난, 세상의 유혹은 누구에게나 주어질 수 있다.
- 우리는 믿음으로 눈으로 현상을 바라볼 수 있어야 한다. 
- 그리고 세상 유혹에서 벗어날 수 있는 단단한 믿음이 내 안에 생겨야 한다.
- 죽을만큼 힘든 고난이 아직 내게 없었기 때문에 이런 생각을 했을 수도 있다. 
- 그러나 중요한 것은 그런 상황에서 하나님을 의지할 수 있는 믿음, 하나님을 의지할 수 있는 은혜가 나에게 주어지길 소망해야 한다.
- 과거나 현대나 악함은 여전히 존재하고, 믿음을 가진 많은 영혼이 여전히 무너지고 있다.
- 나 또한 무너질 수 있기 때문에 믿음을 단단하게 만들어야 한다.
- 그렇기에 3331 큐티가 참 귀하고 강력하다. 남청연 모두 3331 큐티의 강력함을 경험해보길 소망한다. 

