4. 주제만들기: 내 몸은 거룩한 주님의 성전

5. 하나님 찾기 (관찰)
- 잡히시던 밤에 축하하신 후 떡을 먹게하시고, 잔을 마시게한 예수님 

6. 인간 찾기 (관찰)
- 먹을 때에 먼저 먹고 취한자가 있으며 교회를 업신여기고, 빈궁한 자를 부끄럽게 여기고 있다고 말하는 바울
- 성찬식은 주님이 오실 때까지 전하는 일에 힘써야 됨을 알려주는 바울
- 떡과 잔을 합당하시 않게 마시는 자는 죄를 짓는 것이라 말하는 바울

7. 하나님 찾기 (해석) 
- 예수님은 잡혀가실 그날 밤에도 우리를 위하여 떡을 떼어주시고, 잔을 마시게 하셨다.
- 하나님의 사랑은 그 크기를 도저히 알 수 없다.

8. 인간(해석):
- 바울은 믿음을 선택한 자들이 형식적인 신앙에 빠지는 것을 질책했다.
- 공동체를 배려하지 않고 먼저 먹고 취하는 성도들, 교회를 업신여긴 성도들, 빈궁한 자를 챙기지 않는 성도들의 모습은, 오늘날 우리의 교회와 비슷한 모습이다.
- 개인의 신앙생활은 있지만 공동체를 위한 신앙생활은 없는 나의 신앙생활도 반성하고 점검해보아야 한다.
- 자기중심적인 신앙생활에 빠지게하는 사탄의 전략에 속아서는 안되겠다.   

9. 적용(나): 
- 개인의 신앙생활도 중요하지만, 공동체를 사랑으로 섬길 수 있는 마음이 내 안에 가득하길 소망한다.

10. 영적터치(단어/구절)
- 교회를 업신여기고 빈궁한 자들을 부끄럽게 하느냐

