7. 하나님 찾기(해석)

8. 인간 찾기(해석)
바울은 성령께서 믿는 모든 이들에게 각종 은사를 주신다고 말하고 있다. 그 은사의 종류로는 지혜와 지식의 말씀, 치유와 예언 등이고, 심지어 믿음의 은사까지 포함된다고 밝히고 있다.

각자 받은 은사는 서로의 유익을 위하여 섬기며 연합하는 데 사용하는 것이 바람직하다는 깨우침을 얻게 된다.

바울은 은사를 자신의 우월성을 드러내거나 자랑의 도구로 사용하는 것이 옳지 않음을 간접적으로 보여주고 있다. 

8절을 보면 바울은 의도적으로 “성령으로 말미암아”, 이어서 “성령을 따라”라고 기록하고 있는데, 이를 통해 모든 은사를 주신 주인이 누구인지에 대한 핵심을 분명히 붙잡고 있음을 알 수 있다.

이러한 본질을 바울처럼 붙들고 있다면, 자신이 지닌 재능으로 인해 스스로 높아지는 죄악을 미리 경계하고 방지할 수 있을 것이다.

훗날 우리 사랑하는 남청연(남북 청년 연합 선교회) 이 지금보다 크게 부흥할 때, 나를 포함한 모든 회원이 자신의 노력과 은사가 아니라 ‘오직 성령 하나님께서 다 하셨습니다’라고 겸손히 고백하는 최고의 유익이 임하기를 기도한다.

9. 적용 (구체적으로)
이미 받은 은사를 잘 활용하여 겸손한 마음으로 다른 사람의 유익을 위하여 잘 사용해야겠다.
은사를 주신 성령 하나님께 감사의 시간을 드려야겠다.

