5. 하나님 찾기 (관찰)

6. 인간 찾기 (관찰)
- 은사를 교회에 덕을 세우기 위해 풍성해지도록 구하라 권면하는 바울
- 영과 마음으로 기도하길 권면하는 바울
- 방언으로 기도하는 자는 하나님께 감사를 드렸으나 그로 인해 덕을 세우지 못하는 성도가 있음을 알려주는 바울
- 교회에서 남을 위해 일만 마디 방언보다 다섯 마디 말이 더 나음을 알려주는 바울

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 은사는 다양하다. 그러나 우리는 체험과 현상으로 은사를 뽐내고 싶은 마음이 있다.
- 방언을 하는 사람도 있고, 하지 못하는 사람도 있다. 
- 방언을 하지 못하는 사람은 하나님으로부터 선물을 받지 못한 것일까? 전혀 그렇지 않다.
- 우리에게 주어진 은사는 다양하고 내게 주어진 은사로 교만함이 생겨서는 안된다.

- 신앙생활에는 완급조절이 필요하다. 
- 가령 처음 자전거를 접한 사람에게 장거리를 권하는 것은 자전거를 포기하게 만드는 길이다. 
- 자전거를 즐겁게 탈 수 있도록 그 사람에게 속도를 맞춰서 함께 달려주어야 한다.
- 신앙생활도 이와같다. 
- 나는 뜨겁지만 뜨겁지 않는 사람과 동행할 수 있다.
- 반대로 나는 뜨겁지 않지만 뜨거운 사람과 함께 할 수 있다.
- 모든 상황에서 균형을 맞출 수 있는 지혜가 필요하다. 
- 나의 신앙생활과 남청연을 위해 기도해야겠다. 

