6.인간 찾기(관찰)
- 고린도교회에 일부 신자들 중, 죽은 자의 부활이 없다고 주장하는 자가 있었다
- 바울은 이들에게 예수님의 부활을 근거로 죽은 자의 부활이 있다는 것을 말해주고 있다.
- 예수님은 부활하심으로 잠자는 자들의 첫 열매가 되신 것이다.

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 고린도교회 신자들은 사도들 앞에 나타나시고 오백 명 앞에 나타나신 예수님을 본 증인들의 말을 직접들은 사람들이었다.
- 예수님이 돌아가실 때 자기들도 죽을까봐 도망가던 자들이 돌아가신 후에 오백 명이나 갑자기 예수님이 부활하셨다고 자기의 목숨 걸며 예수님을 전할 수는 없는 것이다.
- 이것을 볼 때 예수님의 부활은 확실한 사실이고, 고린도교회 신자들은 이들의 증언을 직접들은 사람들이었다.
- 그럼에도 불구하고 죽은 자의 부활이 없다고 말하는 자들에게 바울은 예수님의 부활을 근거로 죽은 자의 부활이 있음을 설명하고 있는 것이다.
-  예수님께서 부활하셨기에 예수님이 하나님의 아들이심이 명확하게 드러났고, 예수님이 부활하셨기에 교회가 생겨났다.
- 우리가 이 땅에서 살다고 죽고 끝나는 것이 아니라, 예수님의 말씀대로 영원한 삶을 살게 된다는 것이다.
- 예수님이 하나님의 아들이시기 때문에 우리 신자는 영원한 삶이 있음 또한 믿는 것이다.

9.적용(나)
- 이 땅에서 하나님이 주시는 생사화복 중 생명과 복을 누리더라도,
- 생로병사라는 물리 법칙을 벗어날 수는 없으며,
- 악인의 흥왕과 신자들의 여러 가지 고난을 보며 가슴 쓰리고 힘겨운 날들을 비껴나 갈 수는 없다.
- 그러나 이 속에서 우리에게 큰 소망이 있는 것은, 이 땅에서의 삶이 끝이 아니기 때문이다.
- 천국에서 부활체를 입고 영광의 하나님과 함께 산다는 소망을 바라봐야 한다.
- 그곳에서 우리는 우리가 생각할 수 있는 모든 것보다도 일곱 배 이상의 기쁨을 누리며 살아갈 것이다.

