7. 하나님 찾기(해석)

8. 인간 찾기(해석)
부활의 주님을 찬양합니다!!
썩을 수밖에 없고 죽을 수밖에 없으며 지옥으로 갈 수밖에 없는 영혼을, 예수님으로 말미암아 썩지 않게 하시고 죽지 않게 하시며 영원한 천국으로 인도하시는 승리의 하나님께 감사합니다!!
바울은 아마 이러한 마음으로 신자들에게 전하고 있는 것 같다. 

그는 53절에서 “이 썩을 것이 반드시 썩지 아니할 것을 입겠고 이 죽을 것이 죽지 아니함을 입으리로다”라고 선포한다. 신자는 이 땅에서 가장 두려워할 수 있는 ‘죽음’의 문제를 이미 해결 받은 존재라는 것을 알 수 있다. 

이보다 더 안전하고 위로가 되는 보장이 어디 있겠는가?
반면, 이 땅에서 모든 부귀영화를 누린다고 하더라도 구원받지 못한 상태라면 결국 썩은 옷을 입고 영원한 사망의 그늘에 갇히는 불쌍한 처지가 되고 만다.

바울은 이런 진리를 신자들에게 알리며, 혹시 있을 고난 가운데서도 더 이상 흔들리지 말고 항상 주님께서 맡기신 사명을 끝까지 감당하라고 권면하고 있다.

